L015.prev:
The build failed because `ItemRecord.Cursed` is a `short`, and the file assigned an `int` to it. The fix is an explicit `(short)` cast when writing it.

I also changed two `cursed` values in `cases.json`. `2147483647` and `-2147483648` do not fit in a `short`, and `(short)-2147483648` truncates to `0`, which would test "not cursed" when the case means "cursed". I replaced them with the `short` boundaries `32767` and `-32768`, which are still nonzero.

=== FILE: Case.cs ===
using System;
using System.Text.Json;
using Mordor.Core;

public static class Case
{
    static int G(JsonElement a, string k) => a.TryGetProperty(k, out var v) ? v.GetInt32() : 0;

    public static string Run(JsonElement a, Random rng)
    {
        int hasItem = G(a, "item");
        int itemId = G(a, "item_id");
        int cursed = G(a, "cursed");
        int slotIn = G(a, "slot_cursed_in");
        int slotAlign = G(a, "slot_align");
        int charAlign = G(a, "char_align");

        var ch = Character.Create("Test", RaceData.ByName("Human"), Alignment.Neutral, Sex.Male,
                                  new int[6] { 10, 10, 10, 10, 10, 10 });
        ch.Alignment = (Alignment)charAlign;

        var slot = new InventorySlot();
        slot.Alignment = (ItemAlignment)slotAlign;
        slot.SlotCursed = slotIn != 0;

        if (hasItem == 0)
        {
            ch.ApplyEquipCurse(slot, null);
        }
        else
        {
            // Real shareware record used as the carrier of the Cursed value; restored afterwards.
            var rec = H.ItemsById[(short)itemId];
            short old = rec.Cursed;
            rec.Cursed = (short)cursed;
            try { ch.ApplyEquipCurse(slot, rec); }
            finally { rec.Cursed = old; }
        }

        return slot.SlotCursed ? "1" : "0";
    }
}
