using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.Json;
using Mordor.Core;

public static class Case
{
    public static string Run(JsonElement a, Random rng)
    {
        int[] stats = a.GetProperty("stats").EnumerateArray().Select(e => e.GetInt32()).ToArray();

        // Starting state from the reference factory, then overwrite every field the rule reads.
        var c = Character.Create("Tester", RaceData.ByName("Human"), Alignment.Neutral, Sex.Male, stats);
        c.Stats = (int[])stats.Clone();

        // UNVERIFIED: guild membership property names are not in the excerpt. Assumes an
        // indexable guild table with a Level member, in the same order as the C++ guilds array.
        // Unjoined slots are reset to level 0 so the default state does not leak in.
        foreach (var g in c.Guilds) g.Level = 0;
        foreach (var g in a.GetProperty("guilds").EnumerateArray())
            c.Guilds[g[0].GetInt32()].Level = g[1].GetInt32();

        // The equipped-item member of Character is not in the excerpt, so worn items cannot be
        // set here. Fail loudly rather than let the C++ side see worn items the C# side ignores.
        if (a.GetProperty("worn").GetArrayLength() != 0)
            throw new InvalidOperationException("worn items cannot be set: Character equipped-item member unknown");

        var eng = new CombatEngine(c, new List<CombatMonster>(),
            id => H.ItemsById.TryGetValue(id, out var it) ? it : null, rng, false);

        return eng.AttackOf(c).ToString();
    }
}
