#include "mordor/state_character.h"

namespace mordor {

static const Item* findItem(const GameData& d, long long id) {
    for (const auto& it : d.items)
        if (static_cast<long long>(it.id) == id) return &it;
    return nullptr;
}

static Str run_attackOf(const JsonValue& a, Ctx& ctx) {
    // UNVERIFIED: the JsonValue array accessor is not in the excerpt. Assumes at(i) and size().
    const JsonValue& st = A(a, "stats");
    Character c;
    // UNVERIFIED: Character stat field name is not in the excerpt. Assumes an int array named stats.
    for (std::size_t i = 0; i < 6; ++i) c.stats[i] = static_cast<i32>(st.at(i).asInt());

    // Clear every guild slot, then apply the case's memberships.
    // UNVERIFIED: GuildMembership member names (guild level) are not in the excerpt.
    for (auto& g : c.guilds) g.level = 0;
    const JsonValue& gs = A(a, "guilds");
    for (std::size_t i = 0; i < gs.size(); ++i) {
        const JsonValue& pair = gs.at(i);
        c.guilds[static_cast<std::size_t>(pair.at(0).asInt())].level = static_cast<i32>(pair.at(1).asInt());
    }

    Inventory inv;
    const JsonValue& wn = A(a, "worn");
    for (std::size_t i = 0; i < wn.size(); ++i) {
        const Item* it = findItem(ctx.data, wn.at(i).asInt());
        if (it) inv.worn.push_back(*it);
    }

    i32 r = attackOf(ctx, c, inv);
    return I(r);
}

const CopyEntry kCopies[] = {
    {"attackOf", &run_attackOf},
};
const std::size_t kNumCopies = 1;

