using System;
using System.Collections.Generic;
using System.Linq;
using System.Reflection;
using System.Text.Json;
using Mordor.Core;

public static class Case
{
    static int Get(JsonElement a, string k) => a.GetProperty(k).GetInt32();

    static void Seg(List<Monster> sel, int s, int c, int d)
    {
        for (int k = 0; k < c; k++) sel.Add(H.Monsters[s + k * d]);
    }

    // The reference's Combat class is not resolvable from the usings above
    // (CS0103), so locate the public static ClassRanges method by reflection
    // in the loaded assemblies. This still calls the reference method itself.
    static MethodInfo _ref;

    static MethodInfo FindRef()
    {
        if (_ref != null) return _ref;
        foreach (var asm in AppDomain.CurrentDomain.GetAssemblies())
        {
            Type[] types;
            try { types = asm.GetTypes(); }
            catch (ReflectionTypeLoadException ex) { types = ex.Types.Where(t => t != null).ToArray(); }
            foreach (var t in types)
            {
                if (t.Name != "Combat") continue;
                var m = t.GetMethod("ClassRanges", BindingFlags.Public | BindingFlags.Static);
                if (m != null) { _ref = m; return m; }
            }
        }
        throw new InvalidOperationException("Combat.ClassRanges not found");
    }

    // The rule takes no Random; rng is unused here.
    public static string Run(JsonElement a, Random rng)
    {
        List<Monster> list;
        if (Get(a, "full") == 1)
        {
            list = H.Monsters.ToList();
        }
        else
        {
            var sel = new List<Monster>();
            Seg(sel, Get(a, "s1"), Get(a, "c1"), Get(a, "d1"));
            Seg(sel, Get(a, "s2"), Get(a, "c2"), Get(a, "d2"));
            list = sel;
        }

        int[,] r = (int[,])FindRef().Invoke(null, new object[] { list });
        var parts = new List<string>();
        for (int c = 0; c < r.GetLength(0); c++)
        {
            parts.Add(r[c, 0].ToString());
            parts.Add(r[c, 1].ToString());
        }
        return string.Join("|", parts);
    }
}
