#include "case_api.h"
#include "mordor/monsters1a.h"
#include <vector>

namespace mordor {

static Str flatten_ranges(const Vec<ClassRange>& r) {
    Str s;
    for (std::size_t c = 0; c < r.size(); ++c) {
        if (c) s += "|";
        s += I(r[c].first);
        s += "|";
        s += I(r[c].last);
    }
    return s;
}

static Str run_buildClassRanges(const JsonValue& a, Ctx& ctx) {
    Vec<ClassRange> r;
    if (A(a, "full").asInt() == 1) {
        r = buildClassRanges(ctx);
    } else {
        std::vector<std::size_t> idx;
        auto seg = [&](const char* sk, const char* ck, const char* dk) {
            const long long s = A(a, sk).asInt();
            const long long c = A(a, ck).asInt();
            const long long st = A(a, dk).asInt();
            for (long long k = 0; k < c; ++k)
                idx.push_back(static_cast<std::size_t>(s + k * st));
        };
        seg("s1", "c1", "d1");
        seg("s2", "c2", "d2");

        // Rebuild the monster table as the selected sub-list, same order as C#.
        GameData d = ctx.data;
        decltype(d.monsters) sel;
        for (std::size_t i : idx) sel.push_back(ctx.data.monsters[i]);
        d.monsters = sel;

        Ctx c2(d, ctx.rng, ctx.events);
        r = buildClassRanges(c2);
    }
    return flatten_ranges(r);
}

const CopyEntry kCopies[] = {
    {"buildClassRanges", &run_buildClassRanges},
};
const std::size_t kNumCopies = 1;

} // namespace mordor
=== END FILE ===

