using System.Text.Json;
using Mordor.Core;

public static class Case
{
    public static string Run(JsonElement a, Random rng)
    {
        int level = a.GetProperty("level").GetInt32();
        int x = a.GetProperty("x").GetInt32();
        int y = a.GetProperty("y").GetInt32();
        var f = (Facing)a.GetProperty("facing").GetInt32();

        // H.Dungeon is a List<Floor>. ASSUMPTION: the list is indexed by dungeon level number
        // (matching the C++ side's levelNum == level lookup). Not verified against the loader.
        var floor = H.Dungeon[level];

        var nav = new DungeonNav(floor, x, y, f);
        bool r = nav.CanMove(f);

        // CanMove changes no state; X, Y and Facing are echoed to show they are unchanged.
        return $"{(r ? 1 : 0)}|{nav.X}|{nav.Y}|{(int)nav.Facing}";
    }
}
