bool canMoveFacing(const FloorState& floor, const FloorDef& def, i32 x, i32 y, Facing f);

static Str run_canMoveFacing(const JsonValue& a, Ctx& ctx) {
    i32 level = A(a, "level").asInt();
    i32 x = A(a, "x").asInt();
    i32 y = A(a, "y").asInt();
    Facing f = static_cast<Facing>(A(a, "facing").asInt());

    // ASSUMPTION: ctx.data.dungeon is the C++ analogue of H.Dungeon.
    const FloorDef* def = nullptr;
    for (const auto& d : ctx.data.dungeon) {
        if (d.levelNum == level) { def = &d; break; }
    }
    if (!def) return Str("NOFLOOR");

    // ASSUMPTION: only dungeonLevel is set; squares and areas are left default.
    FloorState floor;
    floor.dungeonLevel = level;

    bool r = canMoveFacing(floor, *def, x, y, f);

    // Same echo as the C# side: return value, then X, Y, Facing (unchanged).
    Str s = I(r ? 1 : 0);
    s += "|"; s += I(x);
    s += "|"; s += I(y);
    s += "|"; s += I(static_cast<long long>(f));
    return s;
}

}  // namespace mordor

