{
    public static string Run(JsonElement a, System.Random rng)
    {
        int w = a.GetProperty("w").GetInt32();
        int h = a.GetProperty("h").GetInt32();
        int x = a.GetProperty("x").GetInt32();
        int y = a.GetProperty("y").GetInt32();
        var facing = (Facing)a.GetProperty("facing").GetInt32();

        var bits = new Dictionary<(int, int), long>();
        foreach (var c in a.GetProperty("cells").EnumerateArray())
        {
            var key = (c.GetProperty("x").GetInt32(), c.GetProperty("y").GetInt32());
            long acc = bits.TryGetValue(key, out var v) ? v : 0L;
            foreach (var f in c.GetProperty("flags").EnumerateArray())
                acc |= 1L << FlagBit(f.GetString()!);
            bits[key] = acc;
        }

        Floor floor = MakeFloor(w, h, bits);
        var nav = new DungeonNav(floor, x, y, facing);
        return Name(nav.EdgeAt(x, y, facing));
    }

    static int FlagBit(string name) => name switch
    {
        "WALL_NORTH" => Floor.WALL_NORTH,
        "DOOR_NORTH" => Floor.DOOR_NORTH,
        "SECRET_DOOR_NORTH" => Floor.SECRET_DOOR_NORTH,
        "WALL_EAST" => Floor.WALL_EAST,
        "DOOR_EAST" => Floor.DOOR_EAST,
        "SECRET_DOOR_EAST" => Floor.SECRET_DOOR_EAST,
        _ => throw new ArgumentException(name)
    };

    static string Name(Edge e) => e switch
    {
        Edge.Wall => "Wall",
        Edge.Door => "Door",
        Edge.SecretDoor => "SecretDoor",
        Edge.Open => "Open",
        _ => throw new InvalidOperationException(e.ToString())
    };

