using System;
using System.Collections.Generic;
using System.Globalization;
using System.Text.Json;
using Mordor.Core;

public static class Case
{
    // Output: "<code>|<index>" where code 0=NoMatch, 1=Selected, 2=Ambiguous.
    // Index is printed only for NoMatch ("-1"); cmdLibrary's reply does not expose
    // the index for Selected or Ambiguous, so both sides print "-" there.
    public static string Run(JsonElement a, Random rng)
    {
        var names = new List<string>();
        foreach (JsonElement n in a.GetProperty("names").EnumerateArray())
            names.Add(n.GetString() ?? "");
        string typed = a.GetProperty("typed").GetString() ?? "";

        var (outcome, index) = LibrarySearch.Find(names, typed);

        int code = outcome switch
        {
            LibrarySearch.Outcome.NoMatch => 0,
            LibrarySearch.Outcome.Selected => 1,
            _ => 2,
        };
        string idx = outcome == LibrarySearch.Outcome.NoMatch
            ? index.ToString(CultureInfo.InvariantCulture)
            : "-";
        return code.ToString(CultureInfo.InvariantCulture) + "|" + idx;
    }
}
