using System;
using System.Collections;
using System.Reflection;
using System.Text.Json;
using Mordor.Core;

public static class Case
{
    // Occupancy is given as a contiguous range [from..to] plus one extra slot (single, -1 = none).
    // from > to means no range. Slot 0 is the hands slot. Indices must stay within _pack (0..39).
    public static string Run(JsonElement a, Random rng)
    {
        int from = a.GetProperty("from").GetInt32();
        int to = a.GetProperty("to").GetInt32();
        int single = a.GetProperty("single").GetInt32();

        var c = Character.Create("Test", RaceData.ByName("Human"), Alignment.Neutral, Sex.Male,
                                 new int[] { 10, 10, 10, 10, 10, 10 });

        // Pack access: the private field _pack that PutInPack writes to.
        var field = typeof(Character).GetField("_pack", BindingFlags.NonPublic | BindingFlags.Instance);
        var pack = (IList)field.GetValue(c);

        for (int i = 0; i < pack.Count; i++) pack[i] = new InventorySlot();
        for (int i = from; i <= to; i++) pack[i] = new InventorySlot { ItemId = 1 };
        if (single >= 0) pack[single] = new InventorySlot { ItemId = 1 };

        bool ok = c.PutInPack(new InventorySlot { ItemId = 999 });

        int idx = -1;
        for (int i = 0; i < pack.Count; i++)
        {
            if (pack[i] is InventorySlot s && s.ItemId == 999) { idx = i; break; }
        }

        return (ok ? 1 : 0) + "|" + idx;
    }
}
