using System;
using System.Collections;
using System.Linq;
using System.Text.Json;
using Mordor.Core;

public static class Case
{
    // Walks up to the first generic type so we can read the slot type of Inventory (a List<T>).
    static Type ElementType(Type t)
    {
        while (t != null && !t.IsGenericType) t = t.BaseType;
        return t.GetGenericArguments()[0];
    }

    public static string Run(JsonElement a, Random rng)
    {
        var c = Character.Create("Test", RaceData.ByName("Human"), Alignment.Neutral, Sex.Male, new int[6]);

        // Character.Create leaves Inventory empty, so grow it to n slots of its own element type.
        int n = a.GetProperty("n").GetInt32();
        var list = (IList)c.Inventory;
        Type elem = ElementType(c.Inventory.GetType());
        while (list.Count < n) list.Add(Activator.CreateInstance(elem));

        // Overwrite every slot so only the case's slots can contribute.
        foreach (var s in c.Inventory)
        {
            s.ItemId = 0;
            s.Equipped = false;
        }

        // Slot k of the case is Inventory position k (C++ side places it at pack[k+1]).
        for (int k = 0; k < n; k++)
        {
            var s = c.Inventory.ElementAt(k);
            s.ItemId = (short)a.GetProperty("id" + k).GetInt32();
            s.Equipped = a.GetProperty("eq" + k).GetInt32() == 1;
        }

        // Unknown or empty ids resolve to null and contribute nothing.
        static Item? Lookup(short id) => H.ItemsById.ContainsKey(id) ? H.ItemsById[id] : null;

        int h = c.HandsUsed(Lookup);
        return h.ToString(System.Globalization.CultureInfo.InvariantCulture);
    }
}
