        var t = o.GetType();
        const BindingFlags f = BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance;
        var p = t.GetProperty(name, f);
        if (p != null) return p.GetValue(o);
        return t.GetField(name, f).GetValue(o);
