using System;
using System.Globalization;
using System.Linq;
using System.Reflection;
using System.Text;
using System.Text.Json;
using Mordor.Core;

public static class Case
{
    // Assumed: raw Currency units are gold x 10000 (matches the C++ side).
    static VbCurrency Money(long raw) => (VbCurrency)(raw / 10000m);

    // VbCurrency has no conversion to decimal. Read its displayed amount via Str(),
    // keep only digits and the decimal point, and apply the sign from '-' or '('.
    static long Raw(VbCurrency v)
    {
        string s = v.Str() ?? "0";
        bool neg = s.Contains('-') || s.Contains('(');
        var digits = new StringBuilder();
        foreach (char c in s)
            if (char.IsDigit(c) || c == '.') digits.Append(c);
        decimal d = digits.Length == 0
            ? 0m
            : decimal.Parse(digits.ToString(), NumberStyles.Number, CultureInfo.InvariantCulture);
        if (neg) d = -d;
        return (long)(d * 10000m);
    }

    public static string Run(JsonElement a, Random rng)
    {
        var raws = a.GetProperty("members").EnumerateArray().Select(e => e.GetInt64()).ToArray();
        int sel = a.GetProperty("selected").GetInt32();

        var chars = new Character[raws.Length];
        for (int i = 0; i < raws.Length; i++)
        {
            // Assumed: null stats is accepted by Character.Create.
            chars[i] = Character.Create("M" + i, RaceData.ByName("Human"), Alignment.Neutral, Sex.Male, null!);
            chars[i].GoldOnHand = Money(raws[i]);
        }

        var party = new Party(chars);
        // SelectedIndex has a private setter; set it by reflection.
        typeof(Party)
            .GetProperty("SelectedIndex", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)!
            .SetValue(party, sel);

        var moved = party.PoolGold();

        var sb = new StringBuilder();
        sb.Append(Raw(moved));
        sb.Append('|').Append(raws.Length);
        foreach (var c in chars)
            sb.Append('|').Append(Raw(c.GoldOnHand));
        return sb.ToString();
    }
}
