// Export wrapper for the file-local copy (defined in shim_death1a.cpp).
void prune_the_dead_death1a_export(Ctx& ctx, Party& party, Arr<bool, kPartyMaxSize>& countedDead);

// Field names for hits / dead / stoned are not in the material. Fails loudly until supplied.
static void setVitalsFromJson(Character& c, const JsonValue& m) {
    (void)c; (void)m;
    throw std::runtime_error("setVitalsFromJson: Vitals/Ailments field names not provided");
}

static Str joinStr(const Vec<Str>& v) {
    Str out;
    for (std::size_t i = 0; i < v.size(); ++i) { if (i) out += ","; out += v[i]; }
    return out;
}

static Str run_pruneTheDead(const JsonValue& a, Ctx& ctx) {
    Party party{};
    const JsonValue& ms = A(a, "members");
    Vec<Str> before;
    for (std::size_t i = 0; i < ms.size(); ++i) {
        const JsonValue& m = ms.at(i);
        Character& c = party.members[i];
        c.name = A(m, "name").asStr();
        setVitalsFromJson(c, m);
        before.push_back(c.name);
    }
    party.size = static_cast<i32>(before.size());

    Arr<bool, kPartyMaxSize> counted{};
    const JsonValue& cnt = A(a, "counted");
    for (std::size_t i = 0; i < cnt.size() && i < kPartyMaxSize; ++i)
        counted[i] = cnt.at(i).asInt() != 0;

    prune_the_dead_death1a_export(ctx, party, counted);

    // Derive removed names: survivors keep their order, so unmatched entries were removed.
    Vec<Str> after;
    for (i32 i = 0; i < party.size; ++i) after.push_back(party.members[i].name);
    Vec<Str> removed;
    std::size_t k = 0;
    for (const Str& b : before) {
        if (k < after.size() && after[k] == b) ++k;
        else removed.push_back(b);
    }

    return I(party.size) + "|" + joinStr(after) + "|" + joinStr(removed);
}

