using System;
using System.Globalization;
using System.Text.Json;
using Mordor.Core;

public static class Case
{
    // Harness guard: the scripted rng repeats its last draw, so a reference loop that
    // keeps rejecting would never end. Count draws and stop with a timeout instead.
    private sealed class Guard : Random
    {
        private readonly Random inner;
        private int draws;

        public Guard(Random inner) { this.inner = inner; }

        public override double NextDouble()
        {
            if (++draws > 100000) throw new TimeoutException("no termination");
            return inner.NextDouble();
        }
    }

    public static string Run(JsonElement a, Random rng)
    {
        int tier = a.GetProperty("tier").GetInt32();
        try
        {
            Monster? m = Rules.QuestMonster(H.Monsters, tier, new Guard(rng));
            int idx = -1;
            if (m != null)
            {
                var list = H.Monsters;
                for (int i = 0; i < list.Count; i++)
                {
                    if (object.ReferenceEquals(list[i], m)) { idx = i; break; }
                }
            }
            // Rules.QuestMonster changes no state; the returned monster's table index is the canonical value.
            return idx.ToString(CultureInfo.InvariantCulture);
        }
        catch (TimeoutException)
        {
            return "NO_TERMINATION";
        }
        catch (Exception e)
        {
            return "EXC:" + e.GetType().Name;
        }
    }
}
