        bool done = a.GetProperty("done").GetInt32() != 0;
        int target = a.GetProperty("target").GetInt32();
        bool consume = a.GetProperty("consume").GetInt32() != 0;
        int start = a.GetProperty("start").GetInt32();
        var pack = a.GetProperty("pack").EnumerateArray().Select(e => e.GetInt32()).ToArray();

        // Starting state: Nomad active, level 1 (from Create). Quest and pack set explicitly.
        var c = Character.Create("Tester", RaceData.ByName("Human"), Alignment.Neutral, Sex.Male,
                                 new int[] { 10, 10, 10, 10, 10, 10 });
        c.Guild.QuestType = qt;
        c.Guild.QuestDone = done;
        c.Guild.QuestTarget = (short)target;
        c.ItemQuestsDone = start;

        // Inventory is read-only (IReadOnlyList). Write the backing field _pack, which
        // RemoveFromPack indexes directly (index 0 = Hands, slots 1..N = carried items).
        // Every slot is overwritten first so no creation defaults remain.
        var packField = typeof(Character).GetField("_pack", BindingFlags.Instance | BindingFlags.NonPublic)
            ?? throw new InvalidOperationException("Character._pack not found");
        var slots = (IList)packField.GetValue(c)!;
        for (int i = 0; i < slots.Count; i++)
            slots[i] = new InventorySlot { ItemId = 0 };
        for (int k = 0; k < pack.Length; k++)
            slots[k + 1] = new InventorySlot { ItemId = (short)pack[k] };

        bool r = c.QuestSatisfied(consume);

        // Canonical form: non-empty pack ids in slot order (matches C++, which skips id 0).
        string ids = string.Join(",", c.Inventory.Where(s => s != null && s.ItemId != 0).Select(s => s.ItemId));
        return string.Join("|", new[] { (r ? 1 : 0).ToString(), ids, c.ItemQuestsDone.ToString() });
    }
