using System;
using System.Text;
using System.Text.Json;
using Mordor.Core;

public static class Case
{
    // Bit k of args.truth / args.seen: 0 WALL_EAST, 1 WALL_NORTH, 2 DOOR_EAST,
    // 3 DOOR_NORTH, 4 SECRET_DOOR_EAST, 5 SECRET_DOOR_NORTH.
    static int BitAt(int k) => k switch
    {
        0 => Floor.WALL_EAST,
        1 => Floor.WALL_NORTH,
        2 => Floor.DOOR_EAST,
        3 => Floor.DOOR_NORTH,
        4 => Floor.SECRET_DOOR_EAST,
        _ => Floor.SECRET_DOOR_NORTH,
    };

    static readonly string[] FacingNames = { "North", "East", "South", "West" };

    static long BitsToFlags(int bits)
    {
        long m = 0;
        for (int k = 0; k < 6; k++)
            if (((bits >> k) & 1) != 0) m |= 1L << BitAt(k);
        return m;
    }

    public static string Run(JsonElement a, System.Random rng)
    {
        int w = a.GetProperty("w").GetInt32();
        int h = a.GetProperty("h").GetInt32();
