#include "case_api.h"
#include "mordor/state_dungeon.h"

namespace mordor {

// Provided by shim_dungeon1a.cpp (appended to src/dungeon1a.cpp).
void shim_recordDoorPassage_dungeon1a(Ctx& ctx, FloorState& floor, i32 x, i32 y, Facing f);
void shim_edgeMasks_dungeon1a(u32* out);

// Facing ordinals follow the C# order: 0 North, 1 East, 2 South, 3 West.
static Facing facingOf(i64 n) { return static_cast<Facing>(n); }

// Bit k of truth/seen = masks[k], in the order
// WALL_EAST, WALL_NORTH, DOOR_EAST, DOOR_NORTH, SECRET_DOOR_EAST, SECRET_DOOR_NORTH.
// truth bits sit on the square the passage examines (same cell rule as OnPassingThrough);
// seen bits sit on every square. Output is the recorded state of each square, per mask.
static Str run_recordDoorPassage(const JsonValue& a, Ctx& ctx) {
    i32 w = (i32)A(a, "w").asInt();
    i32 h = (i32)A(a, "h").asInt();
    i32 x = (i32)A(a, "x").asInt();
    i32 y = (i32)A(a, "y").asInt();
    i64 n = A(a, "facing").asInt();
    Facing f = facingOf(n);
    i64 truth = A(a, "truth").asInt();
    i64 seen = A(a, "seen").asInt();

    u32 masks[6];
    shim_edgeMasks_dungeon1a(masks);

    // Same cell rule as OnPassingThrough.
    i32 cx = x, cy = y;
    if (n == 3) cx = x - 1;
    else if (n != 0 && n != 1) cy = y - 1;

    FloorState floor;
    floor.squares.resize((size_t)(w * h));
    for (i32 j = 0; j < h; j++) {
        for (i32 i = 0; i < w; i++) {
            u32 b = 0;
            for (int k = 0; k < 6; k++)
                if ((seen >> k) & 1) b |= masks[k];
            if (i == cx && j == cy)
                for (int k = 0; k < 6; k++)
                    if ((truth >> k) & 1) b |= masks[k];
            floor.squares[(size_t)(j * w + i)].bits = b;
        }
    }

    shim_recordDoorPassage_dungeon1a(ctx, floor, x, y, f);

    Str out;
    bool first = true;
    for (i32 j = 0; j < h; j++)
        for (i32 i = 0; i < w; i++)
            for (int k = 0; k < 6; k++) {
                if (!first) out += "|";
                first = false;
                u32 b = floor.squares[(size_t)(j * w + i)].bits;
                out += I((b & masks[k]) != 0 ? 1 : 0);
            }
