using System;
using System.Collections.Generic;
using System.Text;
using System.Text.Json;
using Mordor.Core;

public static class Case
{
    private static readonly int[] Codes = { 4, 0, 1, 2, 3 };

    public static string Run(JsonElement a, Random rng)
    {
        try
        {
            return RunInner(a, rng);
        }
        catch (Exception ex)
        {
            // Diagnostic: report the exception instead of aborting the run.
            return "CS_EXC:" + ex.GetType().FullName + ":" + ex.Message;
        }
    }

    private static string RunInner(JsonElement a, Random rng)
    {
        int days = a.GetProperty("days").GetInt32();
        int deepest = a.GetProperty("deepest").GetInt32();
        int ns = a.GetProperty("ns").GetInt32();

        var shelf = new StoreStock();
        for (int i = 0; i < ns; i++)
        {
            int code = a.GetProperty("s" + i).GetInt32();
            shelf.Add((short)(code / 10), ToAlign(code % 10));
        }

        shelf.Replenish(H.Items, days, rng, deepest);

        var sb = new StringBuilder();
        bool first = true;
        foreach (Item it in H.Items)
        {
            foreach (int c in Codes)
            {
                int n = shelf.Count(it.Id, ToAlign(c));
                if (n > 0)
                {
                    if (!first) sb.Append(',');
                    first = false;
                    sb.Append(it.Id).Append('.').Append(c).Append('=').Append(n);
                }
            }
        }
        sb.Append('|').Append(H.F(rng.NextDouble()));
        return sb.ToString();
    }

    private static ItemAlignment ToAlign(int c) => c == 4 ? ItemAlignment.Unaligned : (ItemAlignment)c;
}
