static Str run_replenishStore(const JsonValue& a, Ctx& ctx) {
    const i64 days = A(a, "days").asInt();
    const i32 deepest = static_cast<i32>(A(a, "deepest").asInt());
    const i64 ns = A(a, "ns").asInt();

    Vec<Item> store;
    for (i64 i = 0; i < ns; ++i) {
        char key[16];
        std::snprintf(key, sizeof key, "s%lld", static_cast<long long>(i));
        const i64 code = A(a, key).asInt();
        Item unit{};
        unit.id = static_cast<decltype(unit.id)>(code / 10);
        const i64 c = code % 10;
        unit.alignment = c == 4 ? Unaligned : static_cast<ItemAlign>(static_cast<i32>(c));
        store.push_back(unit);
    }

    replenishStore(ctx, store, days, deepest);

    static const i32 kCodes[5] = {4, 0, 1, 2, 3};
    Str out;
    bool first = true;
    for (const ItemDef& d : ctx.data.items) {
        for (i32 c : kCodes) {
            const ItemAlign al = c == 4 ? Unaligned : static_cast<ItemAlign>(c);
            i64 n = 0;
            for (const Item& o : store) {
                if (o.id == d.id && o.alignment == al) ++n;
            }
            if (n > 0) {
                if (!first) out += ",";
                first = false;
                out += I(d.id);
                out += ".";
                out += I(c);
                out += "=";
                out += I(n);
            }
        }
    }
    out += "|";
    out += F(ctx.rng.nextDouble());
    return out;
}

