using System;
using System.Linq;
using System.Text.Json;
using Mordor.Core;

public static class Case
{
    public static string Run(JsonElement a, Random rng)
    {
        int days = a.GetProperty("days").GetInt32();
        int deepest = a.GetProperty("deepest").GetInt32();

        var pens = Confinement.Fresh(H.Monsters);
        pens.Replenish(H.Monsters, days, rng, deepest);

        // Canonical state: non-empty pen entries, sorted by (Ref, Align); leading count.
        var parts = pens.Entries
            .Where(e => e.Count > 0)
            .OrderBy(e => e.Ref)
            .ThenBy(e => (int)e.Align)
            .Select(e => $"{e.Ref},{(int)e.Align},{e.Count}")
            .ToList();

        return parts.Count + string.Concat(parts.Select(p => "|" + p));
    }
}
