using System;
using System.Linq;
using System.Text.Json;
using Mordor.Core;

public static class Case
{
    static int Gi(JsonElement a, string k) => a.GetProperty(k).GetInt32();
    static int[] Ints(JsonElement a, string k) => a.GetProperty(k).EnumerateArray().Select(e => e.GetInt32()).ToArray();
    static string B(bool b) => b ? "1" : "0";

    // side 0 = east edge, 1 = north edge
    static int SecretBit(int side) => side == 0 ? Floor.SECRET_DOOR_EAST : Floor.SECRET_DOOR_NORTH;
    static int DoorBit(int side) => side == 0 ? Floor.DOOR_EAST : Floor.DOOR_NORTH;
    static int WallBit(int side) => side == 0 ? Floor.WALL_EAST : Floor.WALL_NORTH;

    static void SetFlag(Floor fl, int x, int y, int bit)
    {
        int i = y * fl.Width + x;
        var f = fl.Fields[i];
        f.Flags |= 1L << bit;
        fl.Fields[i] = f;
    }

    // Canonical triple for one edge: recorded secret, recorded door, recorded wall.
    // Out-of-grid squares report 0|0|0 (the reference never touches them).
    static string Edge(SharedMap map, Floor fl, int x, int y, int side, int w, int h)
    {
        if (x < 0 || y < 0 || x >= w || y >= h) return "0|0|0";
        int l = fl.LevelNum;
        return string.Join("|", new[]
        {
            B(map.Recorded(l, x, y, w, SecretBit(side))),
            B(map.Recorded(l, x, y, w, DoorBit(side))),
            B(map.Recorded(l, x, y, w, WallBit(side)))
        });
    }

    public static string Run(JsonElement a, Random rng)
    {
        int w = Gi(a, "w"), h = Gi(a, "h"), x = Gi(a, "x"), y = Gi(a, "y");
        int lvl = Gi(a, "lvl"), ab = Gi(a, "ability5");

        var fl = new Floor { Width = (short)w, Height = (short)h, LevelNum = (short)lvl };
        fl.Fields = new Floor.Field[w * h];

        int[] fog = Ints(a, "fog");
        for (int i = 0; i + 1 < fog.Length; i += 2) SetFlag(fl, fog[i], fog[i + 1], Floor.FOG);

        int[] sec = Ints(a, "secret");
        for (int i = 0; i + 2 < sec.Length; i += 3) SetFlag(fl, sec[i], sec[i + 1], SecretBit(sec[i + 2]));

        var map = new SharedMap();
        int[] rec = Ints(a, "recorded");
