#include "case_api.h"
#include "mordor/dungeon1a.h"
#include "mordor/state_dungeon.h"

namespace mordor {

namespace {

// Canonical triple for one edge: raw secret, door, wall bits as 0/1.
Str edgeTriple(FloorState& floor, const EdgeRef& e) {
    if (!cellInState(floor, e.cx, e.cy)) return Str("0|0|0");
    const SquareState& s = sqAt(floor, e.cx, e.cy);
    return I((s.bits & e.secret) != 0 ? 1 : 0) + Str("|") +
           I((s.bits & e.door) != 0 ? 1 : 0) + Str("|") +
           I((s.bits & e.wall) != 0 ? 1 : 0);
}

// side 0 = east edge, 1 = north edge of square (x, y)
EdgeRef edgeAt(int x, int y, int side) {
    return edgeRefOf(x, y, side == 0 ? Facing::E : Facing::N);
}

}  // namespace

static Str run_rollSecretDoorsOnEntry(const JsonValue& a, Ctx& ctx) {
    const i32 w = A(a, "w").asInt();
    const i32 h = A(a, "h").asInt();
    const i32 x = A(a, "x").asInt();
    const i32 y = A(a, "y").asInt();
    const i32 ability = A(a, "ability5").asInt();

    FloorState floor;
    floor.dungeonLevel = A(a, "lvl").asInt();
    floor.squares.resize(static_cast<std::size_t>(w * h));

    // Truth: secret edges, flat triples [x, y, side].
    const JsonValue& sec = A(a, "secret");
    for (std::size_t i = 0; i + 2 < sec.size(); i += 3) {
        EdgeRef e = edgeAt(sec[i].asInt(), sec[i + 1].asInt(), sec[i + 2].asInt());
        if (cellInState(floor, e.cx, e.cy)) sqAt(floor, e.cx, e.cy).bits |= e.secret;
    }

    // Pre-found secret edges, flat triples [x, y, side]. Encoded as this copy's
    // found state: door set, pending secret cleared.
    const JsonValue& rec = A(a, "recorded");
    for (std::size_t i = 0; i + 2 < rec.size(); i += 3) {
        EdgeRef e = edgeAt(rec[i].asInt(), rec[i + 1].asInt(), rec[i + 2].asInt());
        if (cellInState(floor, e.cx, e.cy)) {
            SquareState& s = sqAt(floor, e.cx, e.cy);
            s.bits |= e.door;
            s.bits &= ~e.secret;
        }
    }

    // Fog and lost-position flags have no parameter in this copy; they are not fed.
    rollSecretDoorsOnEntry(ctx, floor, x, y, ability);

    // Output order matches the reference: own E, own N, west neighbour E, south neighbour N.
    Str out = I(ability);
    out += Str("|") + edgeTriple(floor, edgeAt(x, y, 0));
    out += Str("|") + edgeTriple(floor, edgeAt(x, y, 1));
    out += Str("|") + edgeTriple(floor, edgeRefOf(x, y, Facing::W));
    out += Str("|") + edgeTriple(floor, edgeRefOf(x, y, Facing::S));
    return out;
}

const CopyEntry kCopies[] = {
    {"rollSecretDoorsOnEntry", &run_rollSecretDoorsOnEntry},
};
