using System.Globalization;
using System.Text;
using System.Text.Json;
using Mordor.Core;

public static class Case
{
    public static string Run(JsonElement a, System.Random rng)
    {
        int w = a.GetProperty("w").GetInt32();
        int h = a.GetProperty("h").GetInt32();

        // Synthetic floor: only Width, Height and Fields (with the ROCK flag) are read by IsRock / InBounds.
        // Field is nested in Floor, so it is referenced as Floor.Field.
        var floor = new Floor { Width = (short)w, Height = (short)h, Fields = new Floor.Field[w * h] };
        int rl = a.GetProperty("rock_len").GetInt32();
        for (int i = 0; i < rl; i++)
        {
            int rx = a.GetProperty("rx" + i).GetInt32();
            int ry = a.GetProperty("ry" + i).GetInt32();
            floor.Fields[ry * w + rx].Flags |= 1L << Floor.ROCK;
        }

        // Constructor marks (0,0) explored; clear it so only SetPosition effects remain.
        // Generator guarantees (0,0) is never rock.
        var nav = new DungeonNav(floor, 0, 0);
        nav.Explored.Clear();

        int pl = a.GetProperty("path_len").GetInt32();
        for (int i = 0; i < pl; i++)
        {
            int px = a.GetProperty("px" + i).GetInt32();
            int py = a.GetProperty("py" + i).GetInt32();
            nav.SetPosition(px, py);
        }

        var sb = new StringBuilder();
        for (int y = 0; y < h; y++)
            for (int x = 0; x < w; x++)
                sb.Append(nav.HasMapped(x, y) ? '1' : '0');

        return string.Join("|", new[]
        {
            nav.X.ToString(CultureInfo.InvariantCulture),
            nav.Y.ToString(CultureInfo.InvariantCulture),
            sb.ToString()
        });
    }
}
