public static class Case
{
    // Reference: StoreStock.IdentifyFee (instance). Stock is built with public Add calls,
    // so Count(it.Id, slot.Alignment) returns the scripted stock value.
    public static string Run(JsonElement a, Random rng)
    {
        short id = (short)a.GetProperty("id").GetInt32();
        int known = a.GetProperty("known").GetInt32();
        int stock = a.GetProperty("stock").GetInt32();

        Item it = H.ItemsById[id];

        var shelf = new StoreStock();
        for (int i = 0; i < stock; i++)
            shelf.Add(id, ItemAlignment.Unaligned);

        var slot = new InventorySlot
        {
            Known = (IdLevel)known,
            Alignment = ItemAlignment.Unaligned
        };

        long fee = shelf.IdentifyFee(it, slot);
        return fee.ToString(System.Globalization.CultureInfo.InvariantCulture);
    }
}
