using System;
using System.Collections;
using System.Linq;
using System.Reflection;
using System.Runtime.CompilerServices;
using System.Text.Json;
using Mordor.Core;

// Drives Combat.ChestTick (private) through reflection. The namespace of Combat is not
// known to this harness, so the type is located by its members rather than by name in a
// using directive. Nothing here invents game logic; it only sets the state ChestTick reads.
public static class Case
{
    const BindingFlags Any = BindingFlags.Instance | BindingFlags.Static |
                             BindingFlags.Public | BindingFlags.NonPublic;

    static Type CombatType()
    {
        var found = typeof(Character).Assembly.GetTypes()
            .Where(t => t.Name == "Combat" && t.GetMethod("ChestRoundsOf", Any) != null)
            .ToArray();
        if (found.Length != 1)
            throw new InvalidOperationException("Combat type matches: " + found.Length);
        return found[0];
    }

    static Type MemberType(Type t, string name)
    {
        var f = t.GetField(name, Any);
        if (f != null) return f.FieldType;
        var p = t.GetProperty(name, Any);
        if (p != null) return p.PropertyType;
        throw new MissingMemberException(t.Name, name);
    }

    static void Put(object o, string name, object v)
    {
        var t = o.GetType();
        var f = t.GetField(name, Any);
        if (f != null) { f.SetValue(o, v); return; }
        var p = t.GetProperty(name, Any);
        if (p != null) { p.SetValue(o, v); return; }
        throw new MissingMemberException(t.Name, name);
    }

    public static string Run(JsonElement a, System.Random rng)
    {
        bool hasChest = a.GetProperty("hasChest").GetInt32() != 0;
        int count = a.GetProperty("chestCount").GetInt32();

        var c = Character.Create("T", RaceData.ByName("Human"), Alignment.Neutral, Sex.Male, new int[6]);

        Type ct = CombatType();
        object combat = RuntimeHelpers.GetUninitializedObject(ct);
        Put(combat, "GoldEarned", 100);                       // gold > 0: no gold-gate branch
        Put(combat, "Monsters", Activator.CreateInstance(MemberType(ct, "Monsters")));

        // Chest state: a present chest is a dictionary entry; no chest means no entry.
        var rounds = (IDictionary)Activator.CreateInstance(MemberType(ct, "ChestRounds"));
        if (hasChest) rounds[c] = count;
        Put(combat, "ChestRounds", rounds);

        object party = Activator.CreateInstance(MemberType(ct, "Party"));
        Put(party, "Selected", c);
        Put(combat, "Party", party);

        var roundsOf = ct.GetMethod("ChestRoundsOf", Any);
        var tick = ct.GetMethod("ChestTick", Any);
        var lines = (IEnumerable)tick.Invoke(combat, new object[] { c });

        bool opened = false;
        foreach (object line in lines)                       // force the iterator to run
        {
            var p = line.GetType().GetProperty("OpensChest", Any);
            if (p == null) throw new MissingMemberException(line.GetType().Name, "OpensChest");
            if ((bool)p.GetValue(line)) opened = true;
        }

        int after = (int)roundsOf.Invoke(combat, new object[] { c });
        return (opened ? 1 : 0) + "|" + after;
    }
}
