using System.Linq;
using System.Text.Json;
using Mordor.Core;

public static class Case
{
    // Canonical codes shared with case.cpp: 0 = no refusal, 1 = NotKnown, 2 = SpellLevel, 3 = Stat, 9 = other.
    static int KindCode(RefusalKind k) => k switch
    {
        RefusalKind.NotKnown => 1,
        RefusalKind.SpellLevel => 2,
        RefusalKind.Stat => 3,
        _ => 9,
    };

    public static string Run(JsonElement a, Random rng)
    {
        // Unfit draws no random numbers; rng is unused.
        // "spell" is a 0-based index into H.Spells (105 records); the same index selects ctx.data.spells on the C++ side.
        int spellIdx = a.GetProperty("spell").GetInt32();
        int guildLevel = a.GetProperty("guildLevel").GetInt32();
        Spell s = H.Spells[spellIdx];

        // Stats are the spell's required values plus a per-stat delta, so equal and one-below boundaries are hit exactly.
        var stats = new int[6];
        for (int i = 0; i < 6; i++)
            stats[i] = s.Required[i] + a.GetProperty("d" + i).GetInt32();

        Character c = Character.Create("Tester", RaceData.ByName("Human"), Alignment.Neutral, Sex.Male, stats);
        c.Stats = (int[])stats.Clone();
        c.StatMax = Enumerable.Repeat(99, 6).ToArray();

        if (!c.Guilds.Any(m => m.Guild.ToString() == "Nomad"))
            throw new InvalidOperationException("no Nomad membership");
        foreach (var m in c.Guilds)
            m.Level = m.Guild.ToString() == "Nomad" ? guildLevel : 0;

        Refusal? r = CastGate.Unfit(c, s, 0, true, _ => null);
        int code = r is { } rf ? KindCode(rf.Kind) : 0;
        return code.ToString();
    }
