using System;
using System.Collections.Generic;
using System.Text;
using System.Text.Json;
using Mordor.Core;

public static class Case
{
    static long Num(JsonElement a, string k) =>
        a.TryGetProperty(k, out var v) ? v.GetInt64() : 0;

    // Raw VbCurrency value (1/10000 gold), read through comparison with long. Amounts here are non-negative.
    static long Raw(VbCurrency v)
    {
        long lo = 0, hi = long.MaxValue;
        while (lo < hi)
        {
            long mid = lo + (hi - lo + 1) / 2;
            if (v >= mid) lo = mid; else hi = mid - 1;
        }
        return lo;
    }

    static Character NewChar(string name) =>
        Character.Create(name, RaceData.ByName("Human"), Alignment.Neutral, Sex.Male, new int[6]);

    public static string Run(JsonElement a, Random rng)
    {
        long cost = Num(a, "cost");
        int size = (int)Num(a, "size");
        int payerIndex = (int)Num(a, "payer");
        int fromN = (int)Num(a, "fromN");

        var members = new List<Character>();
        for (int i = 0; i < size; i++)
        {
            string k = i.ToString();
            var c = NewChar("M" + k);
            // Purse is read-only; the on-hand gold it reads from is set here (raw 1/10000 gold units).
            c.GoldOnHand = Num(a, "purse" + k);
            c.GoldInBank = Num(a, "bank" + k);
            c.DungeonLevel = (int)Num(a, "dl" + k);
            if (Num(a, "dead" + k) != 0) c.CurHits = 0;
            members.Add(c);
        }

        Character payer;
        if (payerIndex >= 0 && payerIndex < size) payer = members[payerIndex];
        else
        {
            payer = NewChar("OUT");
            payer.GoldOnHand = Num(a, "outsidePurse");
        }

        List<Character>? fromList = null;
        if (fromN > 0)
        {
            fromList = new List<Character>();
            for (int j = 0; j < fromN; j++)
                fromList.Add(members[(int)Num(a, "from" + j)]);
        }

        List<Party.ShortfallGift>? plan = Party.PlanShortfall(members, payer, cost, fromList);

        bool covered = plan != null;
        List<Party.ShortfallGift> gifts = plan ?? new List<Party.ShortfallGift>();
        var sb = new StringBuilder();
        sb.Append(covered ? 1 : 0).Append('|').Append(gifts.Count);
        foreach (var g in gifts)
            sb.Append('|').Append(members.IndexOf(g.Giver)).Append('|').Append(Raw(g.Amount));
        return sb.ToString();
    }
